const i = $input.first().json;
const accion = String(i.accion ?? '');
const user_id = Number(i.user_id);
const canal = String(i.canal ?? '');
const s = (v, max) => String(v ?? '').trim().slice(0, max);
const n = (v) => Number(v) || 0;
const HOY = "(now() at time zone 'America/Mexico_City')::date";
const DOW = "extract(isodow from now() at time zone 'America/Mexico_City')::int";

// Si la validacion falla se corre esta consulta inofensiva y el error viaja a Formato.
let sql = "select '[]'::json as filas, 0 as coincidencias";
let params = [];
let error = null;
let entrada = {};

const local = (obj) => {
  entrada = obj;
  if (canal === 'telegram') {
    // Por Telegram no se puede tocar el iPhone: se guarda y la aplica el atajo "FICO acciones".
    sql = "insert into pending_local_actions (user_id, accion) values ($1, $2::jsonb) returning json_build_array(accion) as filas, 1 as coincidencias";
    params = [user_id, JSON.stringify(obj)];
  } else {
    sql = "select json_build_array($1::json) as filas, 1 as coincidencias";
    params = [JSON.stringify(obj)];
  }
};

if (!Number.isInteger(user_id) || user_id <= 0) {
  error = 'user_id inválido';
} else if (accion === 'memoria.recordar') {
  const hecho = s(i.texto, 500);
  entrada = { hecho, categoria: s(i.categoria, 50) };
  if (!hecho) error = 'Falta el hecho a recordar';
  else {
    sql = "with n as (insert into memory_facts (user_id, categoria, hecho) values ($1, nullif($2, ''), $3) returning id, hecho) select coalesce(json_agg(n), '[]'::json) as filas, 1 as coincidencias from n";
    params = [user_id, entrada.categoria, hecho];
  }
} else if (accion === 'memoria.perfil') {
  sql = "select coalesce(json_agg(t), '[]'::json) as filas, 0 as coincidencias from (select id, categoria, hecho from memory_facts where user_id = $1 order by id) t";
  params = [user_id];
} else if (accion === 'checklist.ver') {
  sql = "select coalesce(json_agg(t), '[]'::json) as filas, 0 as coincidencias from (select i.id, i.area, i.titulo, l.cumplido from checklist_items i left join checklist_logs l on l.item_id = i.id and l.fecha = " + HOY + " where i.user_id = $1 and i.activo and " + DOW + " = any(i.dias_semana) order by i.area, i.orden) t";
  params = [user_id];
} else if (accion === 'checklist.marcar') {
  const item_id = n(i.item_id);
  const titulo = s(i.texto, 200);
  const cumplido = i.cumplido === true || String(i.cumplido).toLowerCase() === 'true';
  entrada = { item_id, titulo, cumplido, nota: s(i.nota, 300) };
  if (!item_id && !titulo) error = 'Indica el id o parte del título del ítem';
  else {
    // Solo marca si hay exactamente una coincidencia.
    sql = "with c as (select id, titulo from checklist_items where user_id = $1 and activo and (($2::bigint > 0 and id = $2::bigint) or ($2::bigint = 0 and titulo ilike '%' || $3 || '%'))), u as (insert into checklist_logs (item_id, fecha, cumplido, nota) select id, " + HOY + ", $4::boolean, nullif($5, '') from c where (select count(*) from c) = 1 on conflict (item_id, fecha) do update set cumplido = excluded.cumplido, nota = excluded.nota, respondido_en = now() returning item_id) select coalesce((select json_agg(c) from c where (select count(*) from u) = 1), '[]'::json) as filas, (select count(*) from c)::int as coincidencias";
    params = [user_id, item_id, titulo, cumplido, entrada.nota];
  }
} else if (accion === 'gym.rutina') {
  const dia = n(i.dia_semana);
  entrada = { dia_semana: dia };
  sql = "select coalesce(json_agg(t), '[]'::json) as filas, 0 as coincidencias from (select grupo, ejercicio, series, reps, peso_obj from gym_plan where user_id = $1 and dia_semana = case when $2::int between 1 and 7 then $2::int else " + DOW + " end order by orden) t";
  params = [user_id, dia];
} else if (accion === 'gym.registrar') {
  const ejercicio = s(i.ejercicio, 100);
  entrada = { ejercicio, series: Math.trunc(n(i.series)), reps: s(i.reps, 20), peso: n(i.peso), nota: s(i.nota, 300) };
  if (!ejercicio) error = 'Falta el nombre del ejercicio';
  else if (entrada.series < 0 || entrada.series > 50 || entrada.peso < 0 || entrada.peso > 1000) error = 'Series o peso fuera de rango';
  else {
    sql = "with n as (insert into gym_logs (user_id, fecha, ejercicio, series, reps, peso, nota) values ($1, " + HOY + ", $2, nullif($3::int, 0), nullif($4, ''), nullif($5::numeric, 0), nullif($6, '')) returning id, ejercicio, series, reps, peso) select coalesce(json_agg(n), '[]'::json) as filas, 1 as coincidencias from n";
    params = [user_id, ejercicio, entrada.series, entrada.reps, entrada.peso, entrada.nota];
  }
} else if (accion === 'local.alarma') {
  const m = s(i.hora, 5).match(/^(\d{1,2}):(\d{2})$/);
  if (!m || Number(m[1]) > 23 || Number(m[2]) > 59) error = 'La hora debe tener formato HH:MM de 24 horas';
  else local({ tipo: 'alarma', hora: m[1].padStart(2, '0') + ':' + m[2], etiqueta: s(i.etiqueta, 60) || 'FICO' });
} else if (accion === 'local.temporizador') {
  const minutos = Math.trunc(n(i.minutos));
  if (minutos < 1 || minutos > 1440) error = 'Los minutos deben estar entre 1 y 1440';
  else local({ tipo: 'temporizador', minutos });
} else if (accion === 'sistema.estado') {
  sql = "select json_build_array(json_build_object('tareas_pendientes', (select count(*) from tasks where user_id = $1 and estado = 'pendiente'), 'peticiones_hoy', (select count(*) from agent_logs where canal in ('telegram', 'siri') and (created_at at time zone 'America/Mexico_City')::date = " + HOY + "), 'errores_24h', (select count(*) from agent_logs where error is not null and created_at > now() - interval '24 hours'), 'aprobaciones_pendientes', (select count(*) from pending_actions where estado = 'pendiente' and expires_at > now()), 'costo_mes_usd', (select coalesce(sum(costo_usd), 0) from agent_logs where created_at >= date_trunc('month', now())))) as filas, 0 as coincidencias";
  params = [user_id];
} else {
  error = 'Acción desconocida: ' + accion;
}

return [{ json: { accion, canal, entrada, sql, params, error } }];

const p = $('Preparar').first().json;
const r = $input.first().json;
const filas = Array.isArray(r.filas) ? r.filas : [];
const a = p.accion;
let ok = !p.error;
let error = p.error;
let resumen = '';

if (ok) {
  if (a === 'memoria.recordar') resumen = 'Guardado en memoria: ' + filas[0].hecho;
  else if (a === 'memoria.perfil') resumen = filas.length ? filas.length + ' dato(s) en el perfil' : 'El perfil está vacío';
  else if (a === 'checklist.ver') {
    const hechos = filas.filter(f => f.cumplido === true).length;
    resumen = filas.length ? hechos + ' de ' + filas.length + ' ítems cumplidos hoy' : 'No hay ítems de checklist para hoy';
  } else if (a === 'checklist.marcar') {
    if (filas.length === 1) resumen = '"' + filas[0].titulo + '" marcado como ' + (p.entrada.cumplido ? 'cumplido' : 'no cumplido');
    else {
      ok = false;
      error = r.coincidencias === 0 ? 'No encontré un ítem del checklist que coincida' : 'Hay ' + r.coincidencias + ' ítems que coinciden; pide al usuario que precise cuál';
    }
  } else if (a === 'gym.rutina') resumen = filas.length ? 'Rutina de ' + filas[0].grupo + ': ' + filas.length + ' ejercicio(s)' : 'Ese día no hay rutina (descanso)';
  else if (a === 'gym.registrar') resumen = 'Entreno registrado: ' + filas[0].ejercicio;
  else if (a === 'local.alarma' || a === 'local.temporizador') {
    const que = a === 'local.alarma' ? 'Alarma de las ' + filas[0].hora : 'Temporizador de ' + filas[0].minutos + ' minuto(s)';
    resumen = p.canal === 'telegram' ? que + ' en espera: se aplica en el iPhone cuando Rodri toque el botón del mensaje' : que + ' lista';
  } else if (a === 'sistema.estado') resumen = 'FICO funcionando. ' + filas[0].peticiones_hoy + ' peticiones hoy, ' + filas[0].errores_24h + ' errores en 24 horas, ' + filas[0].tareas_pendientes + ' tareas pendientes';
}
if (!ok) resumen = error;

return [{ json: {
  respuesta: { ok, data: filas, resumen, error: ok ? null : error },
  log: [JSON.stringify(p.entrada), JSON.stringify([a]), resumen, ok ? null : error],
} }];
